// src/exemple/Bonjour.java
package exemple;
public class Bonjour { public static void main(String[] args) { System.out.println("OK"); } }

import java.util.Optional;
public class Bonjour {
  static Optional<String> trouver(int id) {
    return id == 1 ? Optional.of("Web") : Optional.empty();
  }
  public static void main(String[] args) {
    System.out.println(trouver(1).orElse("Absent"));
    System.out.println(trouver(2).orElse("Absent"));
  }
}

import java.util.HashMap;
import java.util.Map;
public class Bonjour {
  public static void main(String[] args) {
    Map<String, Integer> comptes = new HashMap<>();
    for (String mot : new String[]{"web", "api", "web"})
      comptes.merge(mot, 1, Integer::sum);
    System.out.println(comptes.getOrDefault("web", 0));
  }
}
